  `client_id`       VARCHAR(128)    NOT NULL,
  `secret_hash`     VARCHAR(255)    NOT NULL,
  `secret_last4`    VARCHAR(8)      NOT NULL,
  `name`            VARCHAR(255)    NOT NULL,
  `owner_type`      ENUM('merchant','service','ops') NOT NULL,
  `owner_id`        VARCHAR(128)    NOT NULL,
  `allowed_scopes`  TEXT            NOT NULL,
  `allowed_ips`     TEXT            NULL,
  `rate_limit_rps`  INT             NOT NULL DEFAULT 0,
  `status`          ENUM('active','suspended','revoked') NOT NULL DEFAULT 'active',
  `expires_at`      DATETIME        NULL,
  `last_used_at`    DATETIME        NULL,
  `created_at`      DATETIME(3)     NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at`      DATETIME(3)     NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_client_id` (`client_id`),
  KEY `idx_owner`         (`owner_type`, `owner_id`),
  KEY `idx_status`        (`status`),
  KEY `idx_last_used`     (`last_used_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='OAuth2 客户端 (shard 08)';

-- ─── revoked_tokens_08 ─────────────────────────────────────────
CREATE TABLE IF NOT EXISTS `revoked_tokens_08` (
  `jti`         VARCHAR(128) NOT NULL,
  `revoked_at`  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `expires_at`  DATETIME     NOT NULL,
  `client_id`   VARCHAR(128) NULL,
  PRIMARY KEY (`jti`),
  KEY `idx_expires` (`expires_at`),
  KEY `idx_client`  (`client_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='token revocation 黑名单 (shard 08)';

-- ─── admin_audit_08 ────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS `admin_audit_08` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `occurred_at`  DATETIME(3)     NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `actor`        VARCHAR(128)    NOT NULL,
  `action`       VARCHAR(64)     NOT NULL,
  `client_id`    VARCHAR(128)    NULL,
  `source_ip`    VARCHAR(64)     NULL,
  `details`      JSON            NULL,
  `prev_hash`    CHAR(64)        DEFAULT NULL COMMENT 'per-actor chain head',
  `row_hash`     CHAR(64)        NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_actor`     (`actor`),
  KEY `idx_client`    (`client_id`),
  KEY `idx_occurred`  (`occurred_at`),
  KEY `idx_action`    (`action`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='admin 操作审计 (shard 08)';

