-- ─── rsa_keys (全局单表, 不分片; key 数量极少) ─────────────────
CREATE TABLE IF NOT EXISTS `rsa_keys` (
  `kid`          VARCHAR(64)  NOT NULL,
  `private_pem`  TEXT         NOT NULL COMMENT '生产建议 KMS envelope 加密',
  `public_pem`   TEXT         NOT NULL,
  `status`       ENUM('active','retired') NOT NULL DEFAULT 'active',
  `created_at`   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `retired_at`   DATETIME(3)  NULL,
  PRIMARY KEY (`kid`),
  KEY `idx_status` (`status`),
  KEY `idx_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='RSA 签名 key (active + retired)';

-- ─── client_index (全局 client_id → shard 映射; ops 反查 / 跨 shard 用) ──
CREATE TABLE IF NOT EXISTS `client_index` (
  `client_id`    VARCHAR(128) NOT NULL,
  `db_index`     TINYINT      NOT NULL,
  `table_index`  TINYINT      NOT NULL,
  `created_at`   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`client_id`),
  KEY `idx_shard` (`db_index`, `table_index`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='全局 client_id → (db,table) 映射';

